 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = []
    # Every nonzero edge cell projects inward, perpendicular to that edge.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color:
                continue
            if r == 0:
                rays.append((r, c, 1, 0, color))
            elif r == h - 1:
                rays.append((r, c, -1, 0, color))
            elif c == 0:
                rays.append((r, c, 0, 1, color))
            elif c == w - 1:
                rays.append((r, c, 0, -1, color))
    # Construct full inward ray paths, then stop each ray at its first crossing
    # with any other projected ray (including the crossing cell).
    paths = []
    for r, c, dr, dc, color in rays:
        path = []
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            path.append((rr, cc))
            rr += dr
            cc += dc
        paths.append((path, color))
    for i, (path, color) in enumerate(paths):
        stop = len(path) - 1
        for j, (other, _) in enumerate(paths):
            if i == j:
                continue
            common = set(path).intersection(other)
            if common:
                distances = [path.index(cell) for cell in common]
                stop = min(stop, min(distances))
        for rr, cc in path[:stop + 1]:
            if out[rr][cc] == 0 or out[rr][cc] == color:
                out[rr][cc] = color
    return out
